& .card-container {
  display: grid;
  grid-template-columns: auto 1fr;
  box-sizing: border-box;
  position: relative;
  overflow: visible;
  isolation: isolate;

  & .thread-card-column {
    display: flex;
    flex-direction: column;
    gap: var(--thread-pane-container-gap);
    box-sizing: border-box;
    position: relative;
    padding-block: var(--thread-pane-container-gap);
  }

  & .thread-card-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--thread-card-content-gap);
    padding: 0;
    margin: 0;
    line-height: 1.5;
    position: relative;
    isolation: isolate;
  }

  & .thread-card-dynamic-row {
    display: grid;
    grid-template:
      "subject subject" max-content
      "button info" minmax(auto, 1fr)
      / auto 1fr;
    gap: var(--thread-card-content-gap);
    align-items: center;
    padding: 0;
    margin: 0;
    line-height: 1.5;
    position: relative;
    isolation: isolate;
